#' Welch Two-Sample t-Test (Python)
#'
#' 
#' @param data .
#' @param dep .
#' @param group .
#' @param refLevel .
#' @param ciWidth .
#' @param showPlot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$means} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$groups$asDF}
#'
#' \code{as.data.frame(results$groups)}
#'
#' @export
pywelch <- function(
    data,
    dep = NULL,
    group = NULL,
    refLevel,
    ciWidth = 95,
    showPlot = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pywelch requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pywelchOptions$new(
        dep = dep,
        group = group,
        refLevel = refLevel,
        ciWidth = ciWidth,
        showPlot = showPlot,
        showConsole = showConsole)

    analysis <- pywelchClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

